package symbols

import "testing"

// Expected values were generated by running the former Python src/symbols.py on the same inputs.
var cases = []struct {
	input, normalized string
	crypto, option    bool
	optionType, pair  string
}{
	{"SPY", "SPY", false, false, "", "SPY"},
	{" spy ", "SPY", false, false, "", "SPY"},
	{"btc", "BTC/USD", true, false, "", "BTC/USD"},
	{"BTCUSD", "BTC/USD", true, false, "", "BTC/USD"},
	{"btc/usd", "BTC/USD", true, false, "", "BTC/USD"},
	{"BTC/USD", "BTC/USD", true, false, "", "BTC/USD"},
	{"ETH/USD", "ETH/USD", true, false, "", "ETH/USD"},
	{"ETHUSD", "ETHUSD", false, false, "", "ETH/USD"},
	{"ethusdt", "ETHUSDT", false, false, "", "ETH/USDT"},
	{"SOLUSDC", "SOLUSDC", false, false, "", "SOL/USDC"},
	{"ETHBTC", "ETHBTC", false, false, "", "ETH/BTC"},
	{"USD", "USD", false, false, "", "USD"},
	{"BTC1", "BTC1", false, false, "", "BTC1"},
	{"SPY261014C00580000", "SPY261014C00580000", false, true, "call", "SPY261014C00580000"},
	{"spy261014p00580000", "SPY261014P00580000", false, true, "put", "SPY261014P00580000"},
	{" QQQ261013P00740000 ", "QQQ261013P00740000", false, true, "put", "QQQ261013P00740000"},
	{"BRKB261016C00500000", "BRKB261016C00500000", false, true, "call", "BRKB261016C00500000"},
	{"ABCDEFG261014C00580000", "ABCDEFG261014C00580000", false, false, "", "ABCDEFG261014C00580000"},
	{"SPY261014X00580000", "SPY261014X00580000", false, false, "", "SPY261014X00580000"},
	{"SPY26101C00580000", "SPY26101C00580000", false, false, "", "SPY26101C00580000"},
	{"SPY261014C0058000", "SPY261014C0058000", false, false, "", "SPY261014C0058000"},
	{"F261016C00014000", "F261016C00014000", false, true, "call", "F261016C00014000"},
	{"AAPL", "AAPL", false, false, "", "AAPL"},
	{"", "", false, false, "", ""},
}

func TestSymbols(t *testing.T) {
	for _, c := range cases {
		if got := Normalize(c.input); got != c.normalized {
			t.Errorf("Normalize(%q) = %q, want %q", c.input, got, c.normalized)
		}
		if got := IsCrypto(c.input); got != c.crypto {
			t.Errorf("IsCrypto(%q) = %v, want %v", c.input, got, c.crypto)
		}
		if got := IsOption(c.input); got != c.option {
			t.Errorf("IsOption(%q) = %v, want %v", c.input, got, c.option)
		}
		if got := OptionType(c.input); got != c.optionType {
			t.Errorf("OptionType(%q) = %q, want %q", c.input, got, c.optionType)
		}
		if got := CryptoPair(c.input); got != c.pair {
			t.Errorf("CryptoPair(%q) = %q, want %q", c.input, got, c.pair)
		}
	}
}
